package hu.synostream.android;
import android.content.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import org.json.*;import java.util.*;import java.io.*;import java.nio.charset.StandardCharsets;
@RunWith(AndroidJUnit4.class) public class Android0517Test {
 final Android050FlowTest f=new Android050FlowTest();JSONObject other;String old="/Other/Removed.mkv",fresh="/Other/Fresh.Movie.2022.mkv";
 @Before public void init(){f.instrumentation=InstrumentationRegistry.getInstrumentation();f.context=f.instrumentation.getTargetContext();f.app=(SynoApp)f.context.getApplicationContext();f.device=UiDevice.getInstance(f.instrumentation);UiLocale.save(f.context,"hu");}
 @After public void cleanup()throws Exception{f.instrumentation.runOnMainSync(()->{f.app.automaticForeground(false);f.app.cancelScan();f.app.epoch++;});f.cleanup();}
 void waitFor(java.util.function.BooleanSupplier condition)throws Exception{long end=android.os.SystemClock.elapsedRealtime()+30000;while(!condition.getAsBoolean()&&android.os.SystemClock.elapsedRealtime()<end)Thread.sleep(50);assertTrue("Automatic reconciliation did not finish",condition.getAsBoolean());}
 void setup(FakeNas nas)throws Exception{f.setup(nas,List.of());nas.folders.add("/Other");nas.files.put(fresh,new byte[]{1,2,3});other=new JSONObject().put("id","auto-other").put("name","Other fixture").put("movie",true).put("paths",new JSONArray().put("/Other"));f.instrumentation.runOnMainSync(()->{f.app.libraries.put(other);f.app.automaticLibraries.reset();});Library.Card removed=new Library.Card(old,"Removed",true);try(FileOutputStream out=new FileOutputStream(f.app.cacheFile(other))){out.write(new JSONArray().put(removed.json()).toString().getBytes(StandardCharsets.UTF_8));}}
 boolean otherUpdated(){try{return new String(java.nio.file.Files.readAllBytes(f.app.cacheFile(other).toPath()),StandardCharsets.UTF_8).contains("Fresh.Movie")&&!new String(java.nio.file.Files.readAllBytes(f.app.cacheFile(other).toPath()),StandardCharsets.UTF_8).contains("Removed");}catch(Exception e){return false;}}
 @Test public void startupChecksAllLibrariesAndRemovesMissingEntries()throws Exception{try(FakeNas nas=new FakeNas()){setup(nas);f.instrumentation.runOnMainSync(()->f.app.automaticForeground(true));waitFor(()->otherUpdated()&&!f.app.busy&&!f.app.scanRunning);assertTrue(f.app.rawCards.stream().noneMatch(c->c.path.startsWith("/Other")));assertTrue(otherUpdated());}}
 @Test public void pausedActivityDoesNotStartPeriodicScan()throws Exception{try(FakeNas nas=new FakeNas()){setup(nas);f.instrumentation.runOnMainSync(()->f.app.automaticForeground(false));Thread.sleep(1800);assertFalse(f.app.scanRunning);assertFalse(otherUpdated());}}
 @Test public void navigationRemainsAvailableDuringAutomaticInventory()throws Exception{try(FakeNas nas=new FakeNas()){setup(nas);nas.folders.add("/Movies/Slow");nas.gatedFolder="/Movies/Slow";try{f.instrumentation.runOnMainSync(()->f.app.automaticForeground(true));assertTrue(nas.folderEntered.await(15,java.util.concurrent.TimeUnit.SECONDS));assertTrue(f.app.automaticScan);MainActivity activity=f.activity();f.instrumentation.runOnMainSync(()->activity.select(other));waitFor(()->f.app.selectedLibrary.equals("auto-other"));nas.releaseFolder.countDown();waitFor(()->otherUpdated()&&!f.app.busy&&!f.app.scanRunning);assertTrue(f.app.rawCards.stream().allMatch(c->c.path.startsWith("/Other")));}finally{nas.releaseFolder.countDown();}}}
}
